-- GIN index on generated tsvector for full-text search
-- Use STORED generated column so index stays consistent
ALTER TABLE {{table_name}}
  ADD COLUMN IF NOT EXISTS search_vec tsvector
  GENERATED ALWAYS AS (to_tsvector('{{language_config}}', coalesce({{text_column}}, ''))) STORED;

CREATE INDEX CONCURRENTLY IF NOT EXISTS {{index_name}}
  ON {{table_name}} USING GIN (search_vec);

-- Matching query
EXPLAIN ANALYZE
SELECT *, ts_rank(search_vec, q) AS rank
FROM {{table_name}}, websearch_to_tsquery('{{language_config}}', $1) q
WHERE search_vec @@ q
ORDER BY rank DESC
LIMIT 20;
